"""Account gateway and real checkout entry points for the existing static shop."""
def apply(pages, crumb, intro, btn, icon):
    pages['account.html'] = ('Đăng nhập, ví & key — SoraVynx', crumb('Tài khoản') + '''<section class="container narrow"><div class="page-intro"><div class="eyebrow">YOUR SORAVYNX SPACE</div><h1>Tài khoản, ví và key.</h1><p>Đăng nhập hoặc tạo tài khoản để thanh toán QR, nạp ví và xem lại mã truy cập.</p></div><div id="account-gateway" class="checkout-panel" role="status" aria-live="polite"><h2>Đang mở tài khoản của bạn…</h2><p>Vui lòng chờ trong giây lát.</p></div><p class="fine">Không cần tài khoản web nếu bạn chọn mua trực tiếp qua bot Discord.</p><a class="btn secondary" href="discord.html">Xem cách mua qua Discord ↗</a></section>''')
    pages['discord.html'] = ('Mua key qua bot Discord — SoraVynx', crumb('Mua qua Discord') + '''<section class="container"><div class="page-intro"><div class="eyebrow">BUY WHERE YOU CHAT</div><h1>QR và key ngay trong Discord.</h1><p>Chọn gói bằng lệnh /buy. Tin thanh toán và key chỉ hiện riêng cho người mua.</p></div><div class="commerce-steps"><article class="checkout-panel"><span class="step-label">VÀO SERVER</span><h2>Tham gia SoraVynx.</h2><p>Vào server chính thức, tìm kênh cho phép dùng lệnh bot.</p><a class="btn" href="https://discord.gg/J3BevcpAxF" target="_blank" rel="noopener">Vào server Discord ↗</a></article><article class="checkout-panel"><span class="step-label">CHỌN GÓI</span><h2>Gõ <code>/buy</code>.</h2><p>Chọn 7 ngày, 30 ngày, 1 năm hoặc vĩnh viễn ở mục <code>plan</code>. Không dùng lệnh quản trị /keycreate hay /order.</p></article><article class="checkout-panel"><span class="step-label">QUÉT QR</span><h2>Thanh toán đúng đơn.</h2><p>Bot hiện QR BIDV cùng số tiền và mã SVX… Giữ đúng nội dung, kiểm tra người nhận rồi xác nhận trong ứng dụng ngân hàng.</p></article><article class="checkout-panel"><span class="step-label">NHẬN KEY</span><h2>Key tự hiện riêng cho bạn.</h2><p>Khi nhận và đối chiếu tiền xong, bot cập nhật tin QR thành key đã đăng ký. Nếu tin quá lâu hoặc bot khởi động lại, key gửi qua DM; hãy cho phép nhận DM từ server.</p></article></div><div class="notice" style="margin-top:24px">Nếu chưa thấy /buy hoặc đã chuyển tiền mà chưa có key, liên hệ <strong>@vsc.plus</strong>. Giữ mã đơn và biên lai; không chuyển thêm lần nữa. Không gửi mật khẩu hoặc token.</div><div class="commerce-banner"><div><h2>Muốn quản lý số dư trên web?</h2><p>Ví web và đơn mua qua bot là hai luồng riêng. Ví web dùng mua key trong tài khoản web.</p></div><a class="btn secondary" href="account.html">Đăng nhập / đăng ký</a></div></section>''')
    pages['cart.html'] = ('Thanh toán QR hoặc số dư ví — SoraVynx', crumb('Giỏ hàng') + '''<section class="container"><div class="page-intro"><div class="eyebrow">CHOOSE HOW TO PAY</div><h1>Giỏ hàng của bạn.</h1><p>Mỗi gói tạo một đơn riêng và nhận một key. Chọn QR từng đơn hoặc dùng số dư trong tài khoản.</p></div><div id="purchase-empty" class="checkout-panel" hidden><h2>Chưa chọn gói nào.</h2><p>Khám phá các gói key để thêm vào giỏ.</p><a class="btn" href="shop.html">Xem gói key</a></div><div id="purchase-items" class="purchase-list"></div><div class="commerce-banner"><div><h2>Cần nạp ví trước?</h2><p>Đăng nhập, chọn số tiền và quét QR nạp. Ví chỉ cộng sau khi SePay xác nhận giao dịch.</p></div><a class="btn secondary" href="account.html?view=wallet">Mở ví SoraVynx</a></div><div class="checkout-panel" style="margin-top:24px"><h2>Hoặc mua ngay trong Discord.</h2><p>Vào server, dùng /buy, quét QR và nhận key riêng trong bot.</p><a class="btn secondary" href="discord.html">Cách mua qua bot ↗</a></div></section>''')
    pages['orders.html'] = ('Đơn hàng & key của tôi — SoraVynx', crumb('Đơn hàng & key') + '''<section class="container narrow"><div class="page-intro"><div class="eyebrow">YOUR ACCESS LIBRARY</div><h1>Đơn hàng &amp; key của bạn.</h1><p>Đơn mua trên web được lưu trong tài khoản. Đăng nhập để xem key đã đăng ký, trạng thái QR và lịch sử ví.</p></div><div class="checkout-panel"><h2>Mở thư viện key.</h2><p>Key chỉ hiển thị trong tài khoản đã mua. Trạng thái “đang đăng ký” nghĩa là đã nhận tiền và hệ thống đang hoàn tất cấp key.</p><a class="btn" href="account.html?view=orders">Đăng nhập xem key</a></div><p class="fine">Mua qua Discord? Kiểm tra tin /buy hoặc DM của bot. Đơn Discord không tự nhập vào tài khoản web.</p><a href="discord.html">Hướng dẫn mua và nhận key qua bot ↗</a></section>''')
    pages['guide.html'] = ('Cách mua key trên web và Discord — SoraVynx', crumb('Hướng dẫn') + '''<section class="container"><div class="page-intro"><div class="eyebrow">TWO WAYS IN</div><h1>Mua theo cách của bạn.</h1><p>Web để quản lý ví và lịch sử. Discord để quét QR và nhận key ngay trong bot.</p></div><div class="commerce-steps"><article class="checkout-panel"><h2>QR cho từng đơn trên web.</h2><ol><li>Đăng ký hoặc đăng nhập.</li><li>Chọn gói và phương thức QR BIDV.</li><li>Quét QR, giữ đúng số tiền và mã SVX…</li><li>Chờ xác nhận; key hiện ở Đơn hàng &amp; key.</li></ol><a class="btn" href="account.html">Mua trên web</a></article><article class="checkout-panel"><h2>Nạp ví rồi mua key.</h2><ol><li>Mở ví trong tài khoản.</li><li>Nhập số tiền nạp và quét QR của đơn nạp.</li><li>Khi ví đã cộng tiền, chọn gói và “Số dư ví”.</li><li>Hệ thống trừ đúng giá một lần, đăng ký và giao key.</li></ol><a class="btn secondary" href="account.html?view=wallet">Mở ví</a></article><article class="checkout-panel"><h2>Mua qua Discord.</h2><ol><li>Vào server SoraVynx.</li><li>Gõ /buy và chọn plan.</li><li>Quét QR bot gửi riêng.</li><li>Nhận key ở tin QR hoặc DM sau xác nhận.</li></ol><a class="btn secondary" href="discord.html">Hướng dẫn chi tiết ↗</a></article><article class="checkout-panel"><h2>Dùng mã truy cập.</h2><p>Mở bản tool khớp bộ key, nhập mã 15 ký tự đã nhận và bấm “Vào tool”. Cần Internet để kiểm tra key. Thời hạn tính từ lúc cấp.</p><p>Không có cam kết chống ban hoặc luôn tương thích mọi bản cập nhật game. Liên hệ @vsc.plus trước khi mua nếu cần kiểm tra khả năng sử dụng.</p></article></div><div class="notice" style="margin-top:24px">Đã chuyển tiền nhưng chưa có key? Giữ nguyên đơn, mã SVX… và biên lai để hỗ trợ đối soát. Không tự chuyển thêm hoặc tạo đơn mới để trả lại khoản cũ.</div></section>''')
    pages['policy.html'] = ('Chính sách tài khoản, ví & quyền riêng tư — SoraVynx', crumb('Chính sách') + '''<section class="container narrow"><div class="page-intro"><div class="eyebrow">CLEAR FROM THE START</div><h1>Rõ ràng trước khi mua.</h1><p>Thông tin về tài khoản, thanh toán và dữ liệu được lưu.</p></div><div class="checkout-panel policy-copy"><h2>Tài khoản và key</h2><p>Tài khoản web dùng tên đăng nhập và mật khẩu. Mật khẩu được băm kèm salt; phiên đăng nhập dùng cookie bảo mật HttpOnly. Hiện chưa có tự đặt lại mật khẩu qua email; liên hệ @vsc.plus khi cần hỗ trợ, không gửi mật khẩu.</p><p>Đơn và key trên web gắn với tài khoản mua. Đơn qua Discord giao riêng cho người dùng lệnh /buy và chưa tự liên kết với tài khoản web. Mã key hiện không giới hạn theo thiết bị; giữ riêng mã đã nhận.</p><h2>QR và số dư ví</h2><p>Hệ thống tạo QR cho đúng tài khoản ảo BIDV và mã đơn. Chỉ xác nhận từ thông báo SePay đã kiểm tra; ảnh biên lai hoặc nút bấm của người mua không tự cộng ví hay cấp key.</p><p>Đơn QR có hiệu lực 30 phút. Ví chỉ dùng để mua key trên web; không phải tài khoản ngân hàng. Số dư và giao dịch được lưu ở máy chủ, không dựa vào dữ liệu trình duyệt. Yêu cầu hoàn tiền, chuyển sai nội dung hoặc sai số tiền cần liên hệ hỗ trợ để đối soát, chưa xử lý tự động.</p><h2>Dữ liệu và vận hành</h2><p>Máy chủ lưu tên đăng nhập, mật khẩu đã băm, phiên, số dư, sổ giao dịch, đơn hàng và key. Trình duyệt chỉ giữ giỏ hàng, mã yêu cầu chống mua lặp và cookie phiên; không lưu mật khẩu hoặc khóa ngân hàng. SePay và ứng dụng ngân hàng xử lý giao dịch chuyển khoản.</p><p>Cổng thanh toán cần kết nối và hoạt động liên tục. Khi dịch vụ tạm ngừng, không chuyển tiền vào QR cũ. Nếu đã chuyển, giữ mã đơn và liên hệ @vsc.plus.</p><h2>Giới hạn sản phẩm</h2><p>Hạn key tính từ lúc cấp; vĩnh viễn là mã không có ngày hết hạn trong cơ chế cấp key, không bảo đảm trò chơi hay dịch vụ luôn hoạt động. SoraVynx là dự án độc lập, không thuộc nhà phát hành. Không cam kết chống ban, tương thích mọi phiên bản game hoặc kết quả trong game.</p><a class="btn secondary" href="support.html">Liên hệ hỗ trợ</a></div></section>''')
    for key,(title,body) in list(pages.items()):
        body=body.replace('https://discord.com/app','https://discord.gg/J3BevcpAxF')
        for old,new in {
            'Kết nối qua Discord':'Chọn QR hoặc ví',
            'Tạo yêu cầu trên web, gửi nội dung đến @vsc.plus để được xác nhận.':'Đăng nhập để quét QR từng đơn hoặc dùng số dư ví. Bạn cũng có thể dùng /buy trong Discord.',
            'Hoàn tất theo hướng dẫn của người bán và bắt đầu thiết lập tool.':'Key tự hiện sau khi nhận tiền và đăng ký xong. Lưu mã để đăng nhập tool.',
            'Chọn thời hạn để tạo yêu cầu đặt key.':'Chọn thời hạn, thanh toán QR hoặc mua bằng số dư ví.',
            'Người bán xác nhận tương thích và thông tin cấp key qua Discord trước khi thanh toán.':'Bạn có thể mua tự động trên web hoặc qua /buy trong server Discord. Xác nhận tương thích trước khi thanh toán.',
            'Không có tài khoản hay nhóm trung gian được xác nhận trên website này.':'Server chính thức có bot /buy để khách mua key tự động; chỉ dùng link mời trên website.',
        }.items():
            body=body.replace(old,new)
        body=body.replace('Chọn gói, tạo yêu cầu rồi sao chép nội dung gửi đến <strong>@vsc.plus</strong> trên Discord.', 'Đăng nhập web để thanh toán QR hoặc mua bằng ví; hoặc vào server Discord dùng /buy. Key tự giao sau khi xác nhận tiền và đăng ký xong.')
        pages[key]=(title,body)
    shop_title,shop_body=pages['shop.html']
    pages['shop.html']=(shop_title,shop_body+'''<section class="container commerce-banner"><div><h2>QR từng đơn hoặc số dư ví.</h2><p>Đăng ký tài khoản để nạp ví, mua key và quản lý lịch sử. Bạn cũng có thể dùng /buy trong Discord để mua riêng qua bot.</p></div><a class="btn" href="account.html">Đăng nhập / đăng ký</a><a class="btn secondary" href="discord.html">Mua qua Discord</a></section>''')
